"use strict";
import Highcharts from "highcharts";
import HighchartsReact from "highcharts-react-official";
import { useMemo } from "react";
import { Flex, Text, styled as uiStyled, useSporeColors } from "ui/src";
import { useMarketContext } from "../../ContextProvider";
import GridItem from "../GridItem";
import { NumberType, useFormatter } from "utils/formatNumbers";
import { IRM_ADDRESS } from "constants/morpho";
const Container = uiStyled(Flex, {
  flexDirection: "column",
  width: "100%",
  marginTop: "$spacing24"
});
const ContentGrid = uiStyled(Flex, {
  display: "flex",
  flexDirection: "row",
  gap: "$gap24",
  width: "100%",
  $lg: {
    flexDirection: "column"
  }
});
const LeftColumn = uiStyled(Flex, {
  flex: 1,
  flexDirection: "column"
});
const RightColumn = uiStyled(Flex, {
  flex: 1,
  height: 250,
  backgroundColor: "$surface1",
  borderRadius: "$spacing12",
  padding: "$spacing12",
  borderWidth: 1,
  borderColor: "$surface2"
});
function shortenAddress(address) {
  if (!address || address.length < 10) return address;
  return `${address.slice(0, 6)}...${address.slice(-4)}`;
}
const TARGET_UTILIZATION = 90;
const IRMBreakdown = () => {
  const colors = useSporeColors();
  const { marketData } = useMarketContext();
  const { formatFiatPrice } = useFormatter();
  const currentUtilization = marketData?.utilizationRate ?? 0;
  const totalSupplyUsd = marketData?.totalSupplyUsd ?? 0;
  const totalBorrowUsd = marketData?.totalBorrowUsd ?? 0;
  const targetBorrowUsd = TARGET_UTILIZATION / 100 * totalSupplyUsd;
  const borrowToTarget = Math.max(0, targetBorrowUsd - totalBorrowUsd);
  const options = useMemo(
    () => ({
      chart: {
        type: "line",
        backgroundColor: "transparent",
        height: 220,
        style: { fontFamily: "Inter, sans-serif" }
      },
      title: { text: void 0 },
      legend: { enabled: false },
      credits: { enabled: false },
      xAxis: {
        min: 0,
        max: 100,
        labels: {
          style: { color: colors.neutral3.val, fontSize: "10px" },
          formatter: function() {
            return this.value + "%";
          }
        },
        lineColor: colors.surface3.val,
        tickColor: "transparent",
        plotLines: [
          {
            color: "#4C82FB",
            dashStyle: "Dot",
            width: 1,
            value: currentUtilization,
            zIndex: 5,
            label: {
              text: "Current",
              rotation: 0,
              y: -80,
              x: -15,
              style: {
                color: colors.neutral2.val,
                fontSize: "10px"
              },
              backgroundColor: "rgba(25, 27, 31, 0.8)",
              padding: 4,
              borderRadius: 8,
              borderWidth: 1,
              borderColor: colors.surface3.val
            }
          },
          {
            color: colors.neutral2.val,
            dashStyle: "Dot",
            width: 1,
            value: TARGET_UTILIZATION,
            zIndex: 5,
            label: {
              text: "Target",
              rotation: 0,
              y: -40,
              x: -15,
              style: {
                color: colors.neutral2.val,
                fontSize: "10px"
              },
              backgroundColor: "rgba(25, 27, 31, 0.8)",
              padding: 4,
              borderRadius: 8,
              borderWidth: 1,
              borderColor: colors.surface3.val
            }
          }
        ]
      },
      yAxis: {
        title: { text: void 0 },
        gridLineColor: colors.surface2.val,
        gridLineDashStyle: "Dash",
        labels: {
          style: { color: colors.neutral3.val, fontSize: "10px" },
          formatter: function() {
            if (Number(this.value) >= 100) return this.value + "%";
            return "";
          }
        },
        min: 0,
        opposite: true
      },
      tooltip: { enabled: false },
      plotOptions: {
        line: {
          marker: { enabled: false },
          lineWidth: 2,
          color: "#4C82FB"
        }
      },
      series: [
        {
          type: "line",
          name: "Rate Curve",
          data: [
            [0, 2],
            [currentUtilization, marketData?.borrowRate ?? 5],
            [TARGET_UTILIZATION, 10],
            [95, 150],
            [100, 250]
          ]
        }
      ]
    }),
    [colors, currentUtilization, marketData?.borrowRate]
  );
  if (!marketData) {
    return null;
  }
  return <Container>
      <Text variant="subheading1" color="$neutral1" marginBottom="$spacing16">
        IRM Breakdown
      </Text>

      <ContentGrid>
        <LeftColumn>
          <GridItem label="Target utilization" value={`${TARGET_UTILIZATION.toFixed(2)}%`} />
          <GridItem label="Current utilization" value={`${currentUtilization.toFixed(2)}%`} />
          <GridItem
    label="Borrow amount to target utilization"
    value={formatFiatPrice({ price: borrowToTarget, type: NumberType.FiatTokenStats })}
  />
          <GridItem
    label="Interest rate model"
    value={shortenAddress(IRM_ADDRESS)}
    copyable
    externalLink
  />
        </LeftColumn>

        <RightColumn>
          <HighchartsReact highcharts={Highcharts} options={options} />
        </RightColumn>
      </ContentGrid>
    </Container>;
};
export default IRMBreakdown;
