"use strict";
import { createColumnHelper } from "@tanstack/react-table";
import { Table } from "components/Table";
import { Cell } from "components/Table/Cell";
import { HeaderCell, TableText } from "components/Table/styled";
import { MAX_WIDTH_MEDIA_BREAKPOINT } from "components/Tokens/constants";
import { useMemo } from "react";
import { Flex, Text, styled, useSporeColors } from "ui/src";
const TableWrapper = styled(Flex, {
  m: "0 auto",
  maxWidth: MAX_WIDTH_MEDIA_BREAKPOINT,
  width: "100%"
});
function BorrowersTableComponent({ data, loading }) {
  const colors = useSporeColors();
  const columns = useMemo(() => {
    const columnHelper = createColumnHelper();
    return [
      columnHelper.accessor("borrowerAddress", {
        id: "borrower",
        header: () => <HeaderCell justifyContent="flex-start">
            <Text variant="body3" color="$neutral2" fontWeight="500">
              Borrower
            </Text>
          </HeaderCell>,
        cell: (info) => <Cell height="100%" justifyContent="flex-start" loading={loading}>
            <Flex row alignItems="center" gap="$gap8">
              <div
          style={{
            width: 20,
            height: 20,
            backgroundColor: info.row.original.borrowerColor,
            borderRadius: "50%"
          }}
        />
              <TableText>{info.getValue()}</TableText>
            </Flex>
          </Cell>,
        size: 200
      }),
      columnHelper.accessor("collateralAmount", {
        id: "collateral",
        header: () => <HeaderCell justifyContent="flex-start">
            <Text variant="body3" color="$neutral2" fontWeight="500">
              Collateral
            </Text>
          </HeaderCell>,
        cell: (info) => {
          const row = info.row.original;
          return <Cell height="100%" justifyContent="flex-start" loading={loading}>
              <Flex row alignItems="center" gap="$gap8">
                <TableText>
                  {row.collateralAmount} {row.collateralToken}
                </TableText>
                <Flex
            backgroundColor="$surface3"
            paddingHorizontal="$spacing8"
            paddingVertical="$spacing2"
            borderRadius="$roundedFull"
          >
                  <Text variant="body2" color="$neutral2">
                    {row.collateralUsd}
                  </Text>
                </Flex>
              </Flex>
            </Cell>;
        },
        size: 250
      }),
      columnHelper.accessor("loanAmount", {
        id: "loan",
        header: () => <HeaderCell justifyContent="flex-start">
            <Text variant="body3" color="$neutral2" fontWeight="500">
              Loan
            </Text>
          </HeaderCell>,
        cell: (info) => {
          const row = info.row.original;
          return <Cell height="100%" justifyContent="flex-start" loading={loading}>
              <Flex row alignItems="center" gap="$gap8">
                <TableText>
                  {row.loanAmount} {row.loanToken}
                </TableText>
                <Flex
            backgroundColor="$surface3"
            paddingHorizontal="$spacing8"
            paddingVertical="$spacing2"
            borderRadius="$roundedFull"
          >
                  <Text variant="body2" color="$neutral2">
                    {row.loanUsd}
                  </Text>
                </Flex>
              </Flex>
            </Cell>;
        },
        size: 250
      }),
      columnHelper.accessor("ltv", {
        id: "ltv",
        header: () => <HeaderCell justifyContent="flex-start">
            <Text variant="body3" color="$neutral2" fontWeight="500">
              LTV
            </Text>
          </HeaderCell>,
        cell: (info) => <Cell height="100%" justifyContent="flex-start" loading={loading}>
            <TableText>{info.getValue()}</TableText>
          </Cell>,
        size: 150
      }),
      columnHelper.accessor("borrowShare", {
        id: "share",
        header: () => <HeaderCell justifyContent="flex-start">
            <Text variant="body3" color="$neutral2" fontWeight="500">
              Borrow Share
            </Text>
          </HeaderCell>,
        cell: (info) => {
          const isHigh = info.row.original.isHighShare;
          return <Cell height="100%" justifyContent="flex-start" loading={loading}>
              <Flex row alignItems="center" gap="$gap8">
                {
            /* Visual indicator logic */
          }
                <div
            style={{
              width: 16,
              height: 16,
              borderRadius: "50%",
              border: isHigh ? "4px solid #4C82FB" : "4px solid #293249"
              // Blue vs Grey
            }}
          />
                <TableText>{info.getValue()}</TableText>
              </Flex>
            </Cell>;
        },
        size: 150
      })
    ];
  }, [loading]);
  return <Table columns={columns} data={data} loading={loading} maxWidth={1200} tableType="vaultx" tableHeight={64} />;
}
export default function BorrowersTable() {
  return <TableWrapper>
      <BorrowersTableComponent data={[]} loading={false} />
    </TableWrapper>;
}
